$('runbulk').onclick=()=>{try{$('bulkError').textContent='';const p=profile();if(!p.confirmed)throw Error('Select a configured market: Amazon supports UK, France and Germany; other channels use UK calculations.');p.sellerStatus=$('sellerStatus').value;const target=Number($('bulkTarget').value);if($('bulkMode').value==='target'&&(!$('bulkTarget').value.trim()||target>=100))throw Error('Enter a target margin below 100%; negative margins are allowed.');const rows=bulkRows($('paste').value);batch={channel,market:$('market').value,mode:$('bulkMode').value,target,profile:{...p},rows:rows.map(r=>{if(r.error)return r;try{return{...r,breakeven:breakevenPrice(r,p),result:$('bulkMode').value==='target'?findPrice(r,p,target,$('rounding').value):calc(r.sp,r,p),...(p.amazonEU&&p.market==='FR'&&$('bulkMode').value==='actual'&&r.lowest>0?{lowestResult:amazonEUCalc(r.lowest,r,p)}:{})}}catch(e){return{...r,error:e.message}}})};const ok=batch.rows.filter(r=>r.result);$('bulkOutput').hidden=false;$('bulkOutput').innerHTML=`<div class="toolbar"><h2>Analysis Results</h2><span class="badge">${ok.length} calculated · ${batch.rows.length-ok.length} errors</span></div><div class="tablewrap"><table><thead><tr><th>Source row</th><th>Product</th><th>Selling price</th><th>Breakeven Selling Price</th><th>Margin</th><th>Profit</th><th>Status</th></tr></thead><tbody>${batch.rows.map(r=>`<tr><td>${r.line}</td><td>${esc(r.label)}</td>${r.result?`<td>${money(r.result.sp)}</td><td>${r.breakeven?money(r.breakeven.sp):'Unavailable'}</td><td class="${r.result.profit<0?'negative':'positive'}">${r.result.margin.toFixed(2)}%</td><td>${money(r.result.profit)}</td><td>${r.lowestResult?'Lowest '+money(r.lowestResult.sp)+' · profit '+money(r.lowestResult.profit)+' · margin '+r.lowestResult.margin.toFixed(2)+'%':'Calculated'}</td>`:`<td colspan="5" class="error">${esc(r.error)}</td>`}</tr>`).join('')}</tbody></table></div>`;$('export').disabled=false}catch(e){$('bulkError').textContent=e.message;batch=null;$('export').disabled=true;$('bulkOutput').hidden=true}};
$('clearbulk').onclick=()=>{$('paste').value='';$('upload').value='';$('bulkError').textContent='';invalidate()};$('export').onclick=()=>{if(!batch)return;download('MarginForge-'+batch.channel+'-'+batch.market+'.csv',[['Channel',batch.channel],['Market',batch.market],['Currency',MARKETS[batch.market][0]],['Mode',batch.mode],['Target margin',batch.target],['Fee profile',JSON.stringify(batch.profile)],[],['Source row','EAN/ASIN/SKU','Cost','Fulfilment','Shipping','Storage','Delivery','Other','Quantity','AdPercent','SellerStatus','Selling Price','Margin%','Profit','Breakeven Selling Price','Error'],...batch.rows.map(r=>[r.line,r.label,r.cost,r.fulfil,r.shipping,r.storage,r.delivery,r.other,r.quantity??1,r.adRate??0,r.sellerStatus||'',r.result?.revenue,r.result?.margin.toFixed(2),r.result?.profit.toFixed(2),r.breakeven?.sp.toFixed(2),r.error||''])])};
$('runcompare').onclick=()=>{try{$('compareError').textContent='';const r=getProduct();r.sp=Number($('comparePrice').value);if(!$('comparePrice').value.trim()||!Number.isFinite(r.sp)||r.sp<=0)throw Error('Enter a valid selling price for comparison.');$('compareOutput').innerHTML='<table><thead><tr><th>Channel</th><th>Item price</th><th>Total fees</th><th>Profit</th><th>Margin</th></tr></thead><tbody>'+Object.entries(CHANNELS).map(([k,c])=>{const p=profile(k);if(!p.confirmed)return `<tr><td>${c.name}</td><td colspan="4">This channel is not configured for the selected market.</td></tr>`;const a=calc(r.sp,{...r,quantity:Number($('quantity').value),adRate:Number($('adRate').value),sellerStatus:$('sellerStatus').value},p);return `<tr><td><b>${c.name}</b></td><td>${money(a.sp)}</td><td>${money(a.fees)}</td><td class="${a.profit<0?'negative':'positive'}">${money(a.profit)}</td><td>${a.margin.toFixed(2)}%</td></tr>`}).join('')+'</tbody></table>'}catch(e){$('compareError').textContent=e.message}};

function validateWorkbookInputs(r,p){if(!Number.isInteger(r.quantity)||r.quantity<1)throw Error('Units must be a whole number of at least 1.');if(!Number.isFinite(r.adRate)||r.adRate<0||r.adRate>100)throw Error('Advertising rate must be between 0 and 100%.');if(p.channel==='ebay'&&!['top','below'].includes(r.sellerStatus))throw Error('Select Top Rated or Below Standard seller status.');}
function workbookCalc(sp,r,p){if(p.channel==='tiktok')return tiktokCalc(sp,r);validateWorkbookInputs(r,p);if(!Number.isFinite(sp)||sp<=0)throw Error('Selling price must be greater than zero.');const vat=round(sp*20/120),netRevenue=sp-vat,quantity=r.quantity,costs=r.cost*quantity+r.shipping;let commission=0,regulatory=0,belowFee=0,fixed=0,advertising=0,payment=0;
 if(p.channel==='ebay'){commission=round(.109*(sp/quantity))*quantity;regulatory=round(.0035*(sp/quantity))*quantity;if(r.sellerStatus==='below')belowFee=round(.06*(sp/quantity))*quantity;fixed=sp<=10?.30:.40;advertising=round(round(sp*r.adRate/100)*1.2);}
 if(p.channel==='onbuy'){commission=round(sp*.15);advertising=round(sp*r.adRate/100);}
 if(p.channel==='shopify')payment=round(sp*.03+.25);
 const fees=commission+regulatory+belowFee+fixed+advertising+payment;const profit=sp-vat-fees-costs;return{workbook:true,channel:p.channel,sp,revenue:sp,netRevenue,vat,quantity,unitCost:r.cost,shipping:r.shipping,adRate:r.adRate,sellerStatus:r.sellerStatus,commission,regulatory,belowFee,fixed,advertising,payment,costs,fees,profit,margin:profit/netRevenue*100};}
function workbookPrice(r,p,target,style){if(p.channel==='tiktok')return tiktokPrice(r,target,style);validateWorkbookInputs(r,p);if(!Number.isFinite(target)||target>=100)throw Error('Target margin must be below 100%; negative margins are allowed.');const c=p.channel,ad=c==='shopify'?0:r.adRate/100*(c==='ebay'?1.2:1);const feeRate=c==='ebay'?.109+.0035+(r.sellerStatus==='below'?.06:0):c==='onbuy'?.15:.03;const slope=(1-target/100)/1.2-feeRate-ad;if(slope<=0)throw Error('These fees and advertising costs leave no price that meets this target.');const cost=r.cost*r.quantity+r.shipping;const error=.005*(1+Math.abs(target)/100)+.005*r.quantity*(c==='ebay'?(r.sellerStatus==='below'?3:2):0)+(c==='ebay'?.011:c==='onbuy'?.01:.005);const ranges=c==='ebay'?[[1,1000,.30],[1001,10000000,.40]]:[[1,10000000,c==='shopify'?.25:0]];for(const [lo,hi,fixed] of ranges){let cents=snap(Math.max(lo,Math.ceil(Math.max(0,cost+fixed-error)/slope*100-1e-8)),style);while(cents<=hi){const a=workbookCalc(cents/100,r,p);if(a.margin+1e-9>=target)return a;cents=snap(cents+1,style);}}throw Error('No price meets this target within 100,000 currency units.');}
function workbookSummary(p){const rows=p.channel==='ebay'?[['Seller status',$('sellerStatus').value==='below'?'Below Standard Seller':'Top Rated Seller'],['Final value fee','10.9% + 0.35% regulatory fee'],['Fixed order fee','£0.30 at SP ≤ £10; £0.40 above'],['Advertising','Entered ad rate × SP, then × 1.20']]:p.channel==='onbuy'?[['Sales commission','15% of selling price'],['Advertising','Entered ad rate × selling price']]:[['Transaction fee','ROUND(SP × 3% + £0.25, 2)']];return [...rows,['Sales VAT','ROUND(SP × 20 / 120, 2)'],['Product costs','Unit cost × quantity + shipping'],['Margin basis','Profit ÷ selling price excluding VAT']].map(([l,v])=>`<div class="row"><span>${esc(l)}</span><b>${esc(v)}</b></div>`).join('');}
function renderWorkbookSettings(p){$('settingsTitle').textContent=CHANNELS[p.channel].name+' · UK · Excel formula';$('settingsForm').hidden=true;$('settingsNotice').innerHTML='<b>Your spreadsheet calculations are active.</b> Fee rates and rounding follow Pricing Final.xlsx. Use the eBay seller-status selector to include or exclude the additional 6%.';$('settingsInfo').innerHTML=workbookSummary(p);}
function syncWorkbookUI(){const p=profile(),w=p.workbook;$('adField').firstChild.textContent='Advertising rate %';$('lowestField').hidden=!(p.amazonEU&&p.market==='FR'&&mode==='actual');$('amazonCategoryField').hidden=channel!=='amazon';$('rounding').closest('label').hidden=false;$('shipping').closest('label').hidden=false;$('storage').closest('label').firstChild.textContent='Storage / overhead per unit';$('spField').firstChild.textContent=w?'Current order / pack selling price':'Current Selling Price';$('quantityField').hidden=!w;$('adField').hidden=!w||channel==='shopify';$('sellerField').hidden=!w||channel!=='ebay';['fulfil','storage','delivery','other'].forEach(id=>$(id).closest('label').hidden=w);const ship=$('shipping').closest('label');ship.firstChild.textContent=w?'Shipping cost per order':'Inbound shipping / preparation';$('costInfo').textContent=w?'Excel calculation: selling price is the total order / pack price including VAT. Cost = unit cost × units; shipping is deducted once per order. Margin = profit ÷ (selling price − rounded sales VAT).':'Costs must be entered in the selected currency, excluding recoverable VAT. Margin = profit ÷ total customer payment including delivery and sales VAT. Changing market does not convert amounts.';if(p.amazonEU){syncAmazonEUUI(p);return;}if(p.originalAmazon){syncOriginalAmazonUI(p);return;}if(!p.confirmed){$('notice').innerHTML='<b>This channel is not configured for this market.</b> Amazon supports UK, France and Germany. Select UK for eBay, OnCommerce and Shopify.';$('profileSummary').innerHTML='<p class="muted">EU calculations have not been configured yet.</p>';}if(w){$('notice').innerHTML='<b>'+CHANNELS[channel].name+' · UK · Excel calculations</b> — Your spreadsheet formulas are active. '+(channel==='ebay'?'Choose Top Rated to use the current formula, or Below Standard to add 6%.':'Rates and rounding are unchanged from your spreadsheet.');$('profileSummary').innerHTML=workbookSummary(p);$('bulkInstructions').innerHTML='CSV or Excel tab-separated columns: <b>EAN/ASIN/SKU, Cost, Shipping, SellingPrice, Quantity, AdPercent, SellerStatus</b>. Quantity defaults to 1; AdPercent defaults to 0. eBay status can be top or below; blank uses your selector. Other channels ignore SellerStatus. SellingPrice is required for margin analysis.';$('paste').placeholder='EAN/ASIN/SKU,Cost,Shipping,SellingPrice,Quantity,AdPercent,SellerStatus\nSKU-001,8.81,2.4,17.49,1,0,top';}else{$('bulkInstructions').innerHTML='CSV or Excel tab-separated columns: <b>EAN/ASIN/SKU, Cost, Fulfilment, Shipping, Storage, SellingPrice, Delivery, Other</b>. Header required. Blank optional costs are zero.';}if(channel==='tiktok')syncTikTokUI();}
function showWorkbookResult(a){if(a.channel==='tiktok'){showTikTokResult(a);return;}const status=a.channel==='ebay'?(a.sellerStatus==='below'?'Below Standard Seller':'Top Rated Seller'):CHANNELS[a.channel].name;const rows=[['VAT-inclusive selling price',a.sp],['Sales VAT',-a.vat],['Cost of goods ('+a.quantity+' units)',-a.unitCost*a.quantity],['Shipping',-a.shipping],...(a.channel==='ebay'?[['Final value fee (10.9%)',-a.commission],['Regulatory fee (0.35%)',-a.regulatory],['Below Standard fee (6%)',-a.belowFee],['Fixed order fee',-a.fixed],['Advertising fee including 20%',-a.advertising]]:a.channel==='onbuy'?[['Sales fee (15%)',-a.commission],['Advertising fee',-a.advertising]]:[['Transaction fee (3% + £0.25)',-a.payment]])];$('result').innerHTML=`<div class="result"><div class="eyebrow">${mode==='target'?'RECOMMENDED SELLING PRICE':'CURRENT SELLING PRICE'}</div><div class="price">${money(a.sp)}</div><p>${esc(status)} · ${a.quantity} unit(s) · Revenue ex-VAT ${money(a.netRevenue)}</p></div><div class="metrics"><div class="metric"><small>MARGIN ON EX-VAT REVENUE</small><strong class="${a.profit>=0?'positive':'negative'}">${a.margin.toFixed(2)}%</strong></div><div class="metric"><small>NET PROFIT</small><strong class="${a.profit>=0?'positive':'negative'}">${money(a.profit)}</strong></div><div class="metric"><small>TOTAL SELLING FEES</small><strong>${money(a.fees)}</strong></div></div><div class="card"><h2>Order economics · Excel formula</h2>${rows.map(([l,v])=>`<div class="row"><span>${esc(l)}</span><b>${money(v)}</b></div>`).join('')}<div class="row total"><span>Net Profit</span><b style="color:${a.profit>=0?'var(--green)':'#c34848'}">${money(a.profit)}</b></div><p class="muted">Margin = profit ÷ ${money(a.netRevenue)} revenue excluding VAT. Spreadsheet rounding is preserved.</p></div>`;}


function validateAmazonInputs(r){if(!Number.isFinite(r.cost)||r.cost<=0||!Number.isFinite(r.fulfil)||r.fulfil<=0||!Number.isFinite(r.storage)||r.storage<0)throw Error('Enter a positive cost and FBA fee, and a non-negative storage cost.');}
function originalAmazonCalc(sp,r,p){validateAmazonInputs(r);if(!Number.isFinite(sp)||sp<=0)throw Error('Selling price must be greater than zero.');const a=mCalc(sp,r.cost,r.fulfil,r.storage,p.category);return{originalAmazon:true,sp,revenue:sp,vat:a.vat,commission:a.ref,digital:a.dst,profit:a.profit,margin:a.margin*100,costs:r.cost+r.fulfil+r.storage,fees:a.ref+a.dst+r.fulfil+r.storage,cost:r.cost,fulfil:r.fulfil,storage:r.storage,category:p.category};}
function originalAmazonRows(text){const rows=parseCSV(text.replace(/^\uFEFF/,''));if(!rows.length)throw Error('Paste at least one product.');const normalize=x=>x.trim().toLowerCase().replace(/[ _-]/g,'');const headers=rows[0].map(normalize);const header=headers.includes('cost');if(header)rows.shift();if(rows.length>2000)throw Error('Maximum 2,000 products per batch.');return rows.map((cols,i)=>{let r={line:i+(header?2:1),shipping:0,delivery:0,other:0};try{if(header){const raw=Object.fromEntries(headers.map((k,j)=>[k,cols[j]||'']));r.label=raw['ean/asin/sku']||raw.ean||raw.label||raw.asin||raw.sku||'';r.cost=Number(raw.cost||NaN);r.fulfil=Number(raw.fbafee||raw.fulfilment||raw.fbafeeamount||NaN);r.storage=Number(raw.storage||0);r.sp=Number(raw.sellingprice||0);}else{const firstNumeric=cols[0].trim()!==''&&Number.isFinite(Number(cols[0]));const offset=firstNumeric?0:1;r.label=firstNumeric?'':cols[0];r.cost=Number(cols[offset]||NaN);r.fulfil=Number(cols[offset+1]||NaN);r.storage=0;r.sp=0;if(cols[offset+2]){if(Number.isFinite(Number(cols[offset+2])))r.storage=Number(cols[offset+2]);else if(firstNumeric)r.label=cols[offset+2];}}validateAmazonInputs(r);if($('bulkMode').value==='actual'&&r.sp<=0)throw Error('SellingPrice is required to check current margin.');return r;}catch(e){return{...r,error:e.message}}});}
function syncOriginalAmazonUI(p){$('fulfilLabel').firstChild.textContent='FBA fulfilment fee';$('fulfilLabel').querySelector('small').textContent='Enter the FBA fee as in your original calculator.';['shipping','delivery','other'].forEach(id=>$(id).closest('label').hidden=true);$('storage').closest('label').hidden=false;$('storage').closest('label').firstChild.textContent='Storage cost';$('rounding').closest('label').hidden=true;$('costInfo').textContent='Original Amazon calculation: VAT = SP × 20/120; digital services fee = 2% on referral + 2% on FBA. Margin = rounded profit ÷ VAT-inclusive selling price. Recommended prices use your selected price rounding.';$('amazonCategoryHint').innerHTML=CATS[p.category].hint+' · Minimum fee £'+CATS[p.category].minFee.toFixed(2);$('notice').innerHTML='<b>Amazon UK · Original calculator</b> — Category fees, VAT and digital services fees are applied automatically; choose your price rounding.';$('profileSummary').innerHTML=[['Category',CATS[p.category].label],['Referral fee',CATS[p.category].hint],['Digital services fee','2% on referral + 2% on FBA'],['Sales VAT','20/120 of selling price'],['Target price search','Selected rounding · under £500']].map(([l,v])=>`<div class="row"><span>${l}</span><b>${v}</b></div>`).join('');$('bulkInstructions').innerHTML='Paste <b>Cost, FBA fee</b> from Excel, optionally with a label first or third. Optional storage is the third numeric column. Or upload a CSV with <b>EAN/ASIN/SKU, Cost, FBAFee, Storage, SellingPrice</b>. SellingPrice is only required for current-margin analysis.';$('paste').placeholder='7.29\t2.76\n5.50\t2.43\n\nWith labels:\nB0918FHY6P\t7.29\t2.76';}
function showOriginalAmazonResult(a){const rows=[['Selling price (VAT-inclusive)',a.sp],['VAT (20/120 of SP)',-a.vat],['Referral fee ('+rLbl(a.sp,a.category)+')',-a.commission],['Digital services fee (2% + 2%)',-a.digital],['FBA fulfilment fee',-a.fulfil],...(a.storage>0?[['Storage cost',-a.storage]]:[]),['Cost of goods',-a.cost]];$('result').innerHTML=`<div class="result"><div class="eyebrow">${mode==='target'?'RECOMMENDED SELLING PRICE':'CURRENT SELLING PRICE'}</div><div class="price">${money(a.sp)}</div><p>Ex-VAT ${money(a.sp*100/120)} · VAT ${money(a.vat)}</p></div><div class="metrics"><div class="metric"><small>ACTUAL MARGIN</small><strong class="${a.profit>=0?'positive':'negative'}">${a.margin.toFixed(2)}%</strong></div><div class="metric"><small>NET PROFIT</small><strong class="${a.profit>=0?'positive':'negative'}">${money(a.profit)}</strong></div><div class="metric"><small>TOTAL FEES</small><strong>${money(a.fees)}</strong></div></div><div class="card"><h2>Fee breakdown</h2>${rows.map(([l,v])=>`<div class="row"><span>${l}</span><b>${money(v)}</b></div>`).join('')}<div class="row total"><span>Net Profit</span><b style="color:${a.profit>=0?'var(--green)':'#c34848'}">${money(a.profit)}</b></div><p class="muted">Uses the formulas and category rates from your original Amazon calculator.</p></div>`;}


function validateAmazonEU(r){for(const k of ['cost','fulfil','shipping'])if(!Number.isFinite(r[k])||r[k]<0)throw Error('Enter a valid non-negative '+k+' amount.');}
function amazonEUCalc(sp,r,p){validateAmazonEU(r);if(!Number.isFinite(sp)||sp<=0)throw Error('Selling price must be greater than zero.');const vat=sp*p.vat/(100+p.vat),rate=sp<=10?.08:.15,commission=Math.max(.30,sp*rate);const fbaIncrease=p.market==='FR'&&sp>12?(r.fulfil>4?.42:.52):0;const fba=r.fulfil+fbaIncrease;const digitalReferral=round(commission*p.digital/100),digitalFBA=round(fba*p.digital/100);const digital=digitalReferral+digitalFBA;const profit=sp-r.cost-vat-commission-fba-digital-r.shipping;return{amazonEU:true,market:p.market,sp,revenue:sp,vat,commission,rate:rate*100,digital,digitalReferral,digitalFBA,digitalRate:p.digital,baseFBA:r.fulfil,fbaIncrease,fulfil:fba,cost:r.cost,shipping:r.shipping,fees:commission+fba+digital,costs:r.cost+r.shipping,profit,margin:profit/sp*100};}
function amazonEUPrice(r,p,target,style='cent'){validateAmazonEU(r);if(!Number.isFinite(target)||target>=100)throw Error('Enter a target margin below 100%; negative margins are allowed.');const limit=10000000;const ranges=p.market==='FR'?[[1,375,0],[376,1000,.08],[1001,1200,.15],[1201,limit,.15]]:[[1,375,0],[376,1000,.08],[1001,limit,.15]];for(const [lo,hi,refRate]of ranges){const increase=p.market==='FR'&&lo>1200?(r.fulfil>4?.42:.52):0;const fba=r.fulfil+increase;const minimum=refRate===0?.30:0;const fixed=r.cost+r.shipping+fba+round(fba*p.digital/100)+minimum+(minimum?round(minimum*p.digital/100):0);const slope=1/(1+p.vat/100)-refRate*(1+p.digital/100)-target/100;if(slope<=0)continue;const err=minimum?0:.005;let cents=snap(Math.max(lo,Math.ceil(Math.max(0,fixed-err)/slope*100-1e-8)),style);while(cents<=hi){const a=amazonEUCalc(cents/100,r,p);if(a.margin+1e-9>=target)return a;cents=snap(cents+1,style);}}throw Error('No selling price meets this target within 100,000 EUR.');}
function amazonEURows(text){const rows=parseCSV(text.replace(/^\uFEFF/,''));if(rows.length<2)throw Error('Include column headers and at least one product.');if(rows.length>2001)throw Error('Maximum 2,000 products per batch.');const headers=rows.shift().map(h=>h.trim().toLowerCase().replace(/[ _-]/g,''));if(!headers.includes('cost'))throw Error('Cost header is required.');const headerFBA=headers.find(h=>['fbafee','fulfilment','fulfillmentsubtotal','fulfilmentsubtotal'].includes(h));if(!headerFBA)throw Error('Include FBAFee or Fulfillment Subtotal.');return rows.map((row,i)=>{const raw=Object.fromEntries(headers.map((h,j)=>[h,row[j]??'']));const r={line:i+2,label:raw['ean/asin/sku']||raw.ean||raw.label||raw.asin||raw.sku||'',storage:0,delivery:0,other:0};try{for(const [k,col]of [['cost','cost'],['fulfil',headerFBA],['shipping',headers.includes('shippingtoeurope')?'shippingtoeurope':'shipping'],['sp',headers.includes('sellprice')?'sellprice':'sellingprice'],['lowest','lowest']]){const str=(raw[col]||'').trim();if(!str&&(k==='cost'||k==='fulfil'))throw Error('Enter '+k+'.');r[k]=str?Number(str):0;if(!Number.isFinite(r[k])||r[k]<0)throw Error('Invalid '+k+'.');}validateAmazonEU(r);if($('bulkMode').value==='actual'&&r.sp<=0)throw Error('SellingPrice or Sell Price is required.');return r;}catch(e){return{...r,error:e.message};}});}
function syncAmazonEUUI(p){const fr=p.market==='FR';$('amazonCategoryField').hidden=true;['quantity','adRate','storage','delivery','other'].forEach(id=>$(id).closest('label').hidden=true);$('fulfilLabel').hidden=false;$('fulfilLabel').firstChild.textContent=fr?'Base FBA fee (SP at / below €12)':'FBA fulfilment fee';$('fulfilLabel').querySelector('small').textContent=fr?'Above €12: add €0.42 if base FBA > €4, otherwise €0.52.':'FBA fee stays unchanged above €12.';$('shipping').closest('label').hidden=false;$('shipping').closest('label').firstChild.textContent='Shipping to Europe';$('lowestField').hidden=!(fr&&mode==='actual');$('costInfo').textContent='Uses your '+p.market+' spreadsheet: sales VAT '+p.vat+'%, referral fee 8% up to €10 or 15% above (minimum €0.30), and '+p.digital+'% digital fees on referral and effective FBA. Shipping is deducted separately. Margin = unrounded profit ÷ VAT-inclusive selling price.';$('notice').innerHTML='<b>Amazon '+(fr?'France':'Germany')+' · Excel calculations</b> — '+(fr?'FBA increase above €12 is applied automatically.':'FBA remains unchanged when selling price crosses €12.');$('profileSummary').innerHTML=[['Sales VAT',p.vat+'%'],['Referral fee','8% at SP ≤ €10 · 15% above'],['Minimum referral fee','€0.30'],['Digital services fee',p.digital+'% on referral + '+p.digital+'% on FBA'],['FBA price band',fr?'Above €12: +€0.42 / +€0.52':'No price-related increase'],['Margin basis','Profit ÷ VAT-inclusive selling price']].map(([l,v])=>`<div class="row"><span>${l}</span><b>${v}</b></div>`).join('');$('bulkInstructions').innerHTML='Paste your '+p.market+' worksheet with its header row, or use <b>EAN/ASIN/SKU, Cost, FBAFee, Shipping, SellingPrice'+(fr?', Lowest':'')+'</b>. Shipping defaults to zero. SellingPrice is only required for current-margin analysis.';$('paste').placeholder='EAN/ASIN/SKU,Cost,FBAFee,Shipping,SellingPrice'+(fr?',Lowest':'')+'\nSKU-001,2.45,2.29,0.1,9.96'+(fr?',7.55':'');}
function lowestPriceCard(a){return `<div class="card"><h2>Lowest price analysis</h2><div class="row"><span>Lowest selling price</span><b>${money(a.sp)}</b></div><div class="row"><span>Effective FBA fee</span><b>${money(a.fulfil)}</b></div><div class="row"><span>Net Profit</span><b style="color:${a.profit>=0?'var(--green)':'#c34848'}">${money(a.profit)}</b></div><div class="row"><span>Margin on selling price</span><b>${a.margin.toFixed(2)}%</b></div></div>`;}
function showAmazonEUResult(a){const rows=[['Selling price (VAT-inclusive)',a.sp],['Sales VAT ('+(a.market==='FR'?'20/120':'19/119')+' of SP)',-a.vat],['Cost of goods',-a.cost],['Referral fee ('+a.rate+'%, min €0.30)',-a.commission],['Base FBA fee',-a.baseFBA],...(a.market==='FR'?[['FBA increase above €12',-a.fbaIncrease]]:[]),['Digital fee on referral ('+a.digitalRate+'%)',-a.digitalReferral],['Digital fee on FBA ('+a.digitalRate+'%)',-a.digitalFBA],['Shipping to Europe',-a.shipping]];$('result').innerHTML=`<div class="result"><div class="eyebrow">${mode==='target'?'RECOMMENDED SELLING PRICE':'CURRENT SELLING PRICE'}</div><div class="price">${money(a.sp)}</div><p>Ex-VAT ${money(a.sp-a.vat)} · Effective FBA ${money(a.fulfil)}</p></div><div class="metrics"><div class="metric"><small>MARGIN ON SELLING PRICE</small><strong class="${a.profit>=0?'positive':'negative'}">${a.margin.toFixed(2)}%</strong></div><div class="metric"><small>NET PROFIT</small><strong class="${a.profit>=0?'positive':'negative'}">${money(a.profit)}</strong></div><div class="metric"><small>TOTAL AMAZON FEES</small><strong>${money(a.fees)}</strong></div></div><div class="card"><h2>Amazon ${a.market==='FR'?'France':'Germany'} · Fee breakdown</h2>${rows.map(([l,v])=>`<div class="row"><span>${l}</span><b>${money(v)}</b></div>`).join('')}<div class="row total"><span>Net Profit</span><b style="color:${a.profit>=0?'var(--green)':'#c34848'}">${money(a.profit)}</b></div><p class="muted">Full profit precision is retained as in Excel. Only the two digital fee components are rounded before deduction.</p></div>`;}


